const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#main-nav');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle?.getAttribute('aria-expanded')==='true'){toggle.setAttribute('aria-expanded','false');nav.classList.remove('open');toggle.focus();}});
const form=document.querySelector('#booking-form');
if(form){const objet=new URLSearchParams(location.search).get('objet');const radios=Array.from(form.querySelectorAll('[name="objet"]'));const match=radios.find(r=>r.value===objet);if(match)match.checked=true;const date=form.elements.date;const now=new Date();date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const summary=document.querySelector('#summary');summary.replaceChildren();for(const [key,label] of [['objet','Sujet'],['nom','Nom'],['email','E-mail'],['entreprise','Entreprise'],['telephone','Téléphone'],['besoin','Votre besoin'],['date','Date souhaitée'],['creneau','Disponibilité']]){const value=new FormData(form).get(key);if(!value)continue;const term=document.createElement('dt');term.textContent=label;const description=document.createElement('dd');description.textContent=value;summary.append(term,description);}form.hidden=true;const result=document.querySelector('#booking-result');result.hidden=false;result.focus();});
document.querySelector('#edit-request').addEventListener('click',()=>{document.querySelector('#booking-result').hidden=true;form.hidden=false;form.elements.nom.focus();});}
